export const SOURCES: Record<string, string> = {
  "alert-dialog": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// A single-button notice. The caller awaits acknowledgement; the response is void.\n@Component({\n  selector: \"alert-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"alertdialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-title\">{{ call.props().title }}</p>\n        <p class=\"ad-body\" style=\"margin-top: 0.5rem\">{{ call.props().message }}</p>\n        <div class=\"ad-actions\">\n          <button class=\"btn btn-primary\" (click)=\"call.end()\">OK</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass AlertDialog {\n  protected readonly call = injectCallRef<{ title: string; message: string }, void>();\n}\n\nconst Alert = createCallable<{ title: string; message: string }, void>(AlertDialog);\n\n@Component({\n  selector: \"alert-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Show alert</button>\n    <span class=\"ex-status\">{{ acked() ? \"→ acknowledged\" : \"→ awaiting click…\" }}</span>\n  `\n})\nexport class AlertExample {\n  protected readonly acked = signal(false);\n\n  protected async run(): Promise<void> {\n    await Alert.call({ title: \"Heads up\", message: \"Your session will expire in 5 minutes. Save your work to keep it.\" });\n    this.acked.set(true);\n  }\n}\n",
  "bottom-sheet": "import { afterNextRender, Component, computed, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst UNMOUNT_DELAY = 300; // matches the CSS transition so it can animate out\n\ninterface SheetAction {\n  id: string;\n  label: string;\n  icon?: string;\n}\n\n// A mobile-pattern panel that slides up from the bottom. The exit animation is\n// driven by `entered && !call.ended()`, with a matching unmount delay.\n@Component({\n  selector: \"bottom-sheet\",\n  host: {\n    \"(document:keydown.escape)\": \"call.end(null)\",\n    \"(document:mousedown)\": \"onDoc($event)\"\n  },\n  template: `\n    <div class=\"ad-overlay ad-overlay--bottom ad-overlay--animated\" [class.is-closing]=\"!open()\" role=\"dialog\" aria-modal=\"true\" [attr.aria-label]=\"call.props().title\">\n      <div #sheet class=\"ad-sheet\" [class.is-closing]=\"!open()\">\n        <div class=\"ad-grabber\" aria-hidden=\"true\"></div>\n        <p class=\"ad-title\" style=\"padding: 0.25rem 0.5rem\">{{ call.props().title }}</p>\n        <ul class=\"ad-list\">\n          @for (a of call.props().actions; track a.id) {\n            <li>\n              <button (click)=\"call.end(a.id)\" style=\"padding: 0.75rem\">\n                <span style=\"display: flex; align-items: center; gap: 0.75rem\">\n                  @if (a.icon) {\n                    <span aria-hidden=\"true\">{{ a.icon }}</span>\n                  }\n                  <span>{{ a.label }}</span>\n                </span>\n              </button>\n            </li>\n          }\n        </ul>\n      </div>\n    </div>\n  `\n})\nclass BottomSheet {\n  protected readonly call = injectCallRef<{ title: string; actions: readonly SheetAction[] }, string | null>();\n  private readonly sheet = viewChild.required<ElementRef<HTMLElement>>(\"sheet\");\n  private readonly entered = signal(false);\n  protected readonly open = computed(() => this.entered() && !this.call.ended());\n\n  constructor() {\n    afterNextRender(() => this.entered.set(true));\n  }\n\n  protected onDoc(event: MouseEvent): void {\n    if (!this.sheet().nativeElement.contains(event.target as Node)) this.call.end(null);\n  }\n}\n\n// Second arg = unmount delay (ms) so the slide-out can play before teardown.\nconst Sheet = createCallable<{ title: string; actions: readonly SheetAction[] }, string | null>(BottomSheet, UNMOUNT_DELAY);\n\nconst SHEET_ACTIONS: readonly SheetAction[] = [\n  { id: \"share\", label: \"Share\", icon: \"⇪\" },\n  { id: \"copy-link\", label: \"Copy link\", icon: \"⤴\" },\n  { id: \"pin\", label: \"Pin\", icon: \"📌\" },\n  { id: \"archive\", label: \"Archive\", icon: \"🗄\" }\n];\n\n@Component({\n  selector: \"bottom-sheet-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Quick actions</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!last()\">{{ last() ? \"→ \" + last() : \"→ no action yet\" }}</span>\n  `\n})\nexport class BottomSheetExample {\n  protected readonly last = signal<string | null>(null);\n\n  protected async run(): Promise<void> {\n    const id = await Sheet.call({ title: \"Quick actions\", actions: SHEET_ACTIONS });\n    if (id) this.last.set(id);\n  }\n}\n",
  "broadcast-update": "import { Component, computed, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ntype UploadState = \"uploading\" | \"paused\" | \"done\";\nconst UPLOAD_ROW = 52;\nconst STATE_META: Record<UploadState, { icon: string; text: string }> = {\n  uploading: { icon: \"↑\", text: \"uploading…\" },\n  paused: { icon: \"⏸\", text: \"paused\" },\n  done: { icon: \"✓\", text: \"done\" }\n};\n\n// Several stacked pills. A single `update(props)` with no handle merges into\n// EVERY open instance at once, while each keeps its own filename.\n@Component({\n  selector: \"upload-pill\",\n  template: `\n    <div class=\"ad-floating\" [style.right.px]=\"24\" [style.bottom.px]=\"24 + call.index() * UPLOAD_ROW\">\n      <div class=\"ad-upload\">\n        <span aria-hidden=\"true\">{{ meta().icon }}</span>\n        <span class=\"grow\">{{ call.props().label }}</span>\n        <span class=\"state\">{{ meta().text }}</span>\n        <button class=\"ad-close\" aria-label=\"Dismiss\" (click)=\"call.end()\">×</button>\n      </div>\n    </div>\n  `\n})\nclass UploadPill {\n  protected readonly UPLOAD_ROW = UPLOAD_ROW;\n  protected readonly call = injectCallRef<{ label: string; state: UploadState }, void>();\n  protected readonly meta = computed(() => STATE_META[this.call.props().state]);\n}\n\nconst Upload = createCallable<{ label: string; state: UploadState }, void>(UploadPill);\n\n@Component({\n  selector: \"broadcast-update-example\",\n  template: `\n    <div class=\"ex-row\">\n      <button class=\"btn btn-primary\" [disabled]=\"!idle()\" (click)=\"start()\">Start 3 uploads</button>\n      <button class=\"btn\" [disabled]=\"idle()\" (click)=\"toggle()\">Toggle connection</button>\n      <button class=\"btn\" [disabled]=\"idle()\" (click)=\"completeAll()\">Complete all</button>\n    </div>\n    <span class=\"ex-status\">{{ idle() ? \"→ start some uploads, then broadcast to all of them\" : \"connection: \" + (online() ? \"online\" : \"offline\") + \" — \" + openCount() + \" open\" }}</span>\n  `\n})\nexport class BroadcastUpdateExample {\n  private static readonly FILES = [\"report.pdf\", \"photo.jpg\", \"archive.zip\"];\n  protected readonly online = signal(true);\n  protected readonly openCount = signal(0);\n  protected readonly idle = computed(() => this.openCount() === 0);\n\n  protected start(): void {\n    this.online.set(true);\n    for (const label of BroadcastUpdateExample.FILES) {\n      const promise = Upload.call({ label, state: \"uploading\" });\n      this.openCount.update(n => n + 1);\n      promise.then(() => this.openCount.update(n => n - 1));\n    }\n  }\n\n  protected toggle(): void {\n    const next = !this.online();\n    this.online.set(next);\n    // One update, no handle → merges into every open pill; each keeps its label.\n    Upload.update({ state: next ? \"uploading\" : \"paused\" });\n  }\n\n  protected completeAll(): void {\n    this.online.set(true);\n    Upload.update({ state: \"done\" });\n  }\n}\n",
  "caller-resolve": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// The dialog only offers Decline/Approve — but the call can also be settled from\n// the OUTSIDE, without any interaction here, via `Approval.end(handle, value)`.\n@Component({\n  selector: \"approval-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-body\" style=\"color: var(--color-fg)\">Approve: {{ call.props().action }}?</p>\n        <p class=\"ad-subtle\" style=\"text-transform: none; margin-top: 0.25rem\">Auto-declines from the caller if you don't respond in time.</p>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" (click)=\"call.end(false)\">Decline</button>\n          <button class=\"btn btn-primary\" (click)=\"call.end(true)\">Approve</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass ApprovalDialog {\n  protected readonly call = injectCallRef<{ action: string }, boolean>();\n}\n\nconst Approval = createCallable<{ action: string }, boolean>(ApprovalDialog);\n\nconst TIMEOUT_SECONDS = 4;\n\n@Component({\n  selector: \"caller-resolve-example\",\n  template: `\n    <button class=\"btn btn-primary\" [disabled]=\"secondsLeft() !== null\" (click)=\"run()\">Request approval</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"secondsLeft() !== null\">\n      {{ secondsLeft() !== null ? \"auto-declines in \" + secondsLeft() + \"s…\" : status() }}\n    </span>\n  `\n})\nexport class CallerResolveExample {\n  protected readonly status = signal(\"→ no request yet\");\n  protected readonly secondsLeft = signal<number | null>(null);\n\n  protected async run(): Promise<void> {\n    this.status.set(\"awaiting approval…\");\n    // The promise returned by call() IS the call's identity — hold it so the\n    // timeout can settle THIS specific open call from out here.\n    const promise = Approval.call({ action: \"Deploy to production\" });\n\n    let answered = false;\n    promise.then(() => (answered = true));\n\n    let left = TIMEOUT_SECONDS;\n    this.secondsLeft.set(left);\n    const ticker = setInterval(() => {\n      left -= 1;\n      this.secondsLeft.set(left > 0 ? left : null);\n      if (left <= 0) clearInterval(ticker);\n    }, 1000);\n\n    let timedOut = false;\n    const timer = setTimeout(() => {\n      if (answered) return;\n      timedOut = true;\n      Approval.end(promise, false); // resolve from caller scope, targeted at this call\n    }, TIMEOUT_SECONDS * 1000);\n\n    const approved = await promise;\n    clearTimeout(timer);\n    clearInterval(ticker);\n    this.secondsLeft.set(null);\n    this.status.set(approved ? \"→ approved\" : timedOut ? \"→ auto-declined (timed out)\" : \"→ declined\");\n  }\n}\n",
  "color-picker": "import { Component, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// A grid of swatches with visual selection feedback. Resolves with a hex value,\n// or null on Escape / outside-click.\n@Component({\n  selector: \"color-picker\",\n  host: {\n    \"(document:keydown.escape)\": \"call.end(null)\",\n    \"(document:mousedown)\": \"onDoc($event)\"\n  },\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Pick a color\">\n      <div #panel class=\"ad-panel\" style=\"width: auto; max-width: none\">\n        <p class=\"ad-title\" style=\"margin-bottom: 0.75rem\">Pick a color</p>\n        <div class=\"ad-swatches\">\n          @for (color of call.props().swatches; track color) {\n            <button\n              class=\"ad-swatch\"\n              [class.is-selected]=\"color === call.props().current\"\n              [attr.aria-label]=\"color\"\n              [style.background]=\"color\"\n              (click)=\"call.end(color)\"\n            ></button>\n          }\n        </div>\n      </div>\n    </div>\n  `\n})\nclass ColorPicker {\n  protected readonly call = injectCallRef<{ swatches: readonly string[]; current?: string }, string | null>();\n  private readonly panel = viewChild.required<ElementRef<HTMLElement>>(\"panel\");\n\n  protected onDoc(event: MouseEvent): void {\n    if (!this.panel().nativeElement.contains(event.target as Node)) this.call.end(null);\n  }\n}\n\nconst ColorPickerCall = createCallable<{ swatches: readonly string[]; current?: string }, string | null>(ColorPicker);\n\nconst SWATCHES = [\n  \"#ef4444\",\n  \"#f97316\",\n  \"#eab308\",\n  \"#22c55e\",\n  \"#06b6d4\",\n  \"#3b82f6\",\n  \"#8b5cf6\",\n  \"#e11d74\",\n  \"#a3a3a3\",\n  \"#000000\",\n  \"#ffffff\",\n  \"#f59e0b\"\n];\n\n@Component({\n  selector: \"color-picker-example\",\n  template: `\n    <button class=\"ex-swatch-trigger\" (click)=\"run()\">\n      <span class=\"ex-swatch-chip\" [style.background]=\"color()\"></span>\n      <span class=\"ex-status\" style=\"color: var(--color-fg)\">{{ color() }}</span>\n    </button>\n    <span class=\"ex-status\">click to change</span>\n  `\n})\nexport class ColorPickerExample {\n  protected readonly color = signal(\"#e11d74\");\n\n  protected async run(): Promise<void> {\n    const next = await ColorPickerCall.call({ swatches: SWATCHES, current: this.color() });\n    if (next) this.color.set(next);\n  }\n}\n",
  "command-palette": "import { afterNextRender, Component, computed, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ninterface Command {\n  id: string;\n  label: string;\n  shortcut?: string;\n}\n\n// A searchable action list with keyboard navigation (arrows, Enter, Esc).\n// Resolves with the chosen command id, or null on dismiss.\n@Component({\n  selector: \"command-palette\",\n  host: {\n    \"(document:keydown)\": \"onKey($event)\",\n    \"(document:mousedown)\": \"onDoc($event)\"\n  },\n  template: `\n    <div class=\"ad-overlay ad-overlay--top\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Command palette\">\n      <div #panel class=\"ad-palette\">\n        <input #input type=\"text\" placeholder=\"Type a command…\" [value]=\"query()\" (input)=\"query.set($any($event.target).value)\" />\n        <ul class=\"ad-list\">\n          @if (filtered().length === 0) {\n            <li><span class=\"hint\" style=\"display: block; padding: 0.5rem 0.75rem\">No matches</span></li>\n          } @else {\n            @for (cmd of filtered(); track cmd.id; let i = $index) {\n              <li>\n                <button [class.is-active]=\"i === active()\" (mouseenter)=\"active.set(i)\" (click)=\"call.end(cmd.id)\">\n                  <span>{{ cmd.label }}</span>\n                  @if (cmd.shortcut) {\n                    <span class=\"hint\">{{ cmd.shortcut }}</span>\n                  }\n                </button>\n              </li>\n            }\n          }\n        </ul>\n      </div>\n    </div>\n  `\n})\nclass CommandPalette {\n  protected readonly call = injectCallRef<{ commands: readonly Command[] }, string | null>();\n  protected readonly query = signal(\"\");\n  protected readonly active = signal(0);\n  private readonly panel = viewChild.required<ElementRef<HTMLElement>>(\"panel\");\n  private readonly input = viewChild.required<ElementRef<HTMLInputElement>>(\"input\");\n\n  protected readonly filtered = computed(() => {\n    const q = this.query().trim().toLowerCase();\n    const all = this.call.props().commands;\n    return q ? all.filter(c => c.label.toLowerCase().includes(q)) : all;\n  });\n\n  constructor() {\n    afterNextRender(() => this.input().nativeElement.focus());\n  }\n\n  protected onDoc(event: MouseEvent): void {\n    if (!this.panel().nativeElement.contains(event.target as Node)) this.call.end(null);\n  }\n\n  protected onKey(event: KeyboardEvent): void {\n    if (event.key === \"Escape\") this.call.end(null);\n    if (event.key === \"ArrowDown\") {\n      event.preventDefault();\n      this.active.update(a => Math.min(this.filtered().length - 1, a + 1));\n    }\n    if (event.key === \"ArrowUp\") {\n      event.preventDefault();\n      this.active.update(a => Math.max(0, a - 1));\n    }\n    if (event.key === \"Enter\") {\n      event.preventDefault();\n      const item = this.filtered()[this.active()];\n      if (item) this.call.end(item.id);\n    }\n  }\n}\n\nconst Palette = createCallable<{ commands: readonly Command[] }, string | null>(CommandPalette);\n\nconst COMMANDS: readonly Command[] = [\n  { id: \"new-file\", label: \"New file\", shortcut: \"⌘ N\" },\n  { id: \"open\", label: \"Open…\", shortcut: \"⌘ O\" },\n  { id: \"save\", label: \"Save\", shortcut: \"⌘ S\" },\n  { id: \"find\", label: \"Find in files\", shortcut: \"⌘ ⇧ F\" },\n  { id: \"toggle-theme\", label: \"Toggle theme\" },\n  { id: \"restart\", label: \"Restart\" }\n];\n\n@Component({\n  selector: \"command-palette-example\",\n  template: `\n    <button class=\"btn btn-mono\" (click)=\"run()\">⌘ K</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!last()\">{{ last() ? \"→ \" + last() : \"→ no command run yet\" }}</span>\n  `\n})\nexport class CommandPaletteExample {\n  protected readonly last = signal<string | null>(null);\n\n  protected async run(): Promise<void> {\n    const id = await Palette.call({ commands: COMMANDS });\n    if (id) this.last.set(id);\n  }\n}\n",
  "confirm-dialog": "import { Component, computed, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// The dialog, bound once. It reads its arguments from `call.props()` and\n// resolves the awaiting caller with `call.end(value)`.\n@Component({\n  selector: \"confirm-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-body\">{{ call.props().message }}</p>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" (click)=\"call.end(false)\">Cancel</button>\n          <button class=\"btn btn-primary\" (click)=\"call.end(true)\">Continue</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass ConfirmDialog {\n  protected readonly call = injectCallRef<{ message: string }, boolean>();\n}\n\n// Typed, imperative entry point: `await Confirm.call({ message })`.\nconst Confirm = createCallable<{ message: string }, boolean>(ConfirmDialog);\n\n// The trigger: any component, anywhere, just awaits the call.\n@Component({\n  selector: \"confirm-example\",\n  template: `\n    <button class=\"btn btn-danger\" (click)=\"run()\">Delete item</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"status() === 'deleted'\">{{ label() }}</span>\n  `\n})\nexport class ConfirmExample {\n  protected readonly status = signal<\"idle\" | \"deleted\" | \"cancelled\">(\"idle\");\n  protected readonly label = computed(() =>\n    this.status() === \"idle\" ? \"→ awaiting click…\" : this.status() === \"deleted\" ? \"→ deleted\" : \"→ cancelled\"\n  );\n\n  protected async run(): Promise<void> {\n    const accepted = await Confirm.call({ message: \"Delete this item? This action cannot be undone.\" });\n    this.status.set(accepted ? \"deleted\" : \"cancelled\");\n  }\n}\n",
  "context-menu": "import { Component, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ninterface Action {\n  id: string;\n  label: string;\n  destructive?: boolean;\n}\n\n// A right-click menu positioned at the cursor: the caller forwards the click\n// coordinates as plain props, applied via fixed top/left.\n@Component({\n  selector: \"context-menu\",\n  host: {\n    \"(document:keydown.escape)\": \"call.end(null)\",\n    \"(document:mousedown)\": \"onDoc($event)\"\n  },\n  template: `\n    <div #menu class=\"ad-menu\" role=\"menu\" [style.top.px]=\"call.props().y\" [style.left.px]=\"call.props().x\">\n      @for (action of call.props().actions; track action.id) {\n        <button role=\"menuitem\" [class.is-danger]=\"action.destructive\" (click)=\"call.end(action.id)\">{{ action.label }}</button>\n      }\n    </div>\n  `\n})\nclass ContextMenu {\n  protected readonly call = injectCallRef<{ x: number; y: number; actions: readonly Action[] }, string | null>();\n  private readonly menu = viewChild.required<ElementRef<HTMLElement>>(\"menu\");\n\n  protected onDoc(event: MouseEvent): void {\n    if (!this.menu().nativeElement.contains(event.target as Node)) this.call.end(null);\n  }\n}\n\nconst ContextMenuCall = createCallable<{ x: number; y: number; actions: readonly Action[] }, string | null>(ContextMenu);\n\nconst ACTIONS: readonly Action[] = [\n  { id: \"rename\", label: \"Rename\" },\n  { id: \"duplicate\", label: \"Duplicate\" },\n  { id: \"archive\", label: \"Archive\" },\n  { id: \"delete\", label: \"Delete\", destructive: true }\n];\n\n@Component({\n  selector: \"context-menu-example\",\n  template: `\n    <div class=\"ex-target\" (contextmenu)=\"open($event)\">Right-click me</div>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!last()\">{{ last() ? \"→ \" + last() : \"→ no action yet\" }}</span>\n  `\n})\nexport class ContextMenuExample {\n  protected readonly last = signal<string | null>(null);\n\n  protected async open(event: MouseEvent): Promise<void> {\n    event.preventDefault();\n    const action = await ContextMenuCall.call({ x: event.clientX, y: event.clientY, actions: ACTIONS });\n    if (action) this.last.set(action);\n  }\n}\n",
  "error-banner": "import { afterNextRender, Component, DestroyRef, inject, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst BANNER_ROW = 52;\n\n// A transient banner that closes itself after `durationMs`. Multiple calls\n// stack — each is an independent instance positioned by its own `index`.\n@Component({\n  selector: \"error-banner\",\n  template: `\n    <div\n      class=\"ad-floating\"\n      role=\"alert\"\n      aria-live=\"assertive\"\n      [style.top.px]=\"24 + call.index() * BANNER_ROW\"\n      [style.left]=\"'50%'\"\n      [style.transform]=\"'translateX(-50%)'\"\n    >\n      <div class=\"ad-banner\">\n        <span aria-hidden=\"true\">⚠</span>\n        <span class=\"grow\">{{ call.props().message }}</span>\n        <button class=\"ad-close\" aria-label=\"Dismiss\" (click)=\"call.end()\">×</button>\n      </div>\n    </div>\n  `\n})\nclass ErrorBanner {\n  protected readonly BANNER_ROW = BANNER_ROW;\n  protected readonly call = injectCallRef<{ message: string; durationMs: number }, void>();\n\n  constructor() {\n    const destroyRef = inject(DestroyRef);\n    afterNextRender(() => {\n      const timer = setTimeout(() => this.call.end(), this.call.props().durationMs);\n      destroyRef.onDestroy(() => clearTimeout(timer));\n    });\n  }\n}\n\nconst ErrorBannerCall = createCallable<{ message: string; durationMs: number }, void>(ErrorBanner);\n\n@Component({\n  selector: \"error-banner-example\",\n  template: `\n    <button class=\"btn btn-danger\" (click)=\"trigger()\">Simulate error</button>\n    <span class=\"ex-status\">{{ count() > 0 ? count() + (count() === 1 ? \" error triggered\" : \" errors triggered\") : \"no errors yet\" }}</span>\n  `\n})\nexport class ErrorBannerExample {\n  protected readonly count = signal(0);\n\n  protected trigger(): void {\n    this.count.update(c => c + 1);\n    ErrorBannerCall.call({ message: `Network request failed (#${this.count()})`, durationMs: 1500 });\n  }\n}\n",
  "image-lightbox": "import { Component } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// A full-image overlay, closable via backdrop click or the Escape key.\n@Component({\n  selector: \"image-lightbox\",\n  host: { \"(document:keydown.escape)\": \"call.end()\" },\n  template: `\n    <div class=\"ad-overlay ad-overlay--image\" role=\"dialog\" aria-modal=\"true\" [attr.aria-label]=\"call.props().alt\" (click)=\"call.end()\">\n      <img class=\"ad-lightbox-img\" [src]=\"call.props().src\" [alt]=\"call.props().alt\" />\n      <button class=\"ad-lightbox-close\" aria-label=\"Close\" (click)=\"call.end()\">×</button>\n    </div>\n  `\n})\nclass Lightbox {\n  protected readonly call = injectCallRef<{ src: string; alt: string }, void>();\n}\n\nconst LightboxCall = createCallable<{ src: string; alt: string }, void>(Lightbox);\n\ninterface Thumb {\n  thumb: string;\n  full: string;\n  alt: string;\n}\n\nconst THUMBNAILS: readonly Thumb[] = [\n  {\n    thumb: \"https://images.unsplash.com/photo-1518770660439-4636190af475?w=160&h=120&fit=crop\",\n    full: \"https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200\",\n    alt: \"Circuit board macro\"\n  },\n  {\n    thumb: \"https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?w=160&h=120&fit=crop\",\n    full: \"https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?w=1200\",\n    alt: \"Forest path\"\n  },\n  {\n    thumb: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=160&h=120&fit=crop\",\n    full: \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200\",\n    alt: \"Mountains at dusk\"\n  }\n];\n\n@Component({\n  selector: \"image-lightbox-example\",\n  template: `\n    <div class=\"ex-thumbs\">\n      @for (t of thumbnails; track t.thumb) {\n        <button class=\"ex-thumb\" (click)=\"open(t)\"><img [src]=\"t.thumb\" [alt]=\"t.alt\" /></button>\n      }\n    </div>\n    <span class=\"ex-status\">click a thumbnail → lightbox</span>\n  `\n})\nexport class ImageLightboxExample {\n  protected readonly thumbnails = THUMBNAILS;\n\n  protected open(t: Thumb): void {\n    LightboxCall.call({ src: t.full, alt: t.alt });\n  }\n}\n",
  "item-picker": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ninterface Item {\n  id: string;\n  name: string;\n  hint?: string;\n}\n\n// List selection: resolves with the chosen item, or null on cancellation.\n@Component({\n  selector: \"item-picker\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\" [attr.aria-label]=\"call.props().title\">\n      <div class=\"ad-panel\" style=\"max-width: 24rem; padding: 0.5rem\">\n        <div class=\"ad-actions ad-actions--split\" style=\"margin: 0; padding: 0.5rem 0.75rem\">\n          <p class=\"ad-title\" style=\"font-size: 0.9rem\">{{ call.props().title }}</p>\n          <button class=\"ad-close\" aria-label=\"Cancel\" (click)=\"call.end(null)\">×</button>\n        </div>\n        <ul class=\"ad-list\">\n          @for (item of call.props().items; track item.id) {\n            <li>\n              <button (click)=\"call.end(item)\">\n                <span>{{ item.name }}</span>\n                @if (item.hint) {\n                  <span class=\"hint\">{{ item.hint }}</span>\n                }\n              </button>\n            </li>\n          }\n        </ul>\n      </div>\n    </div>\n  `\n})\nclass ItemPicker {\n  protected readonly call = injectCallRef<{ title: string; items: readonly Item[] }, Item | null>();\n}\n\nconst Picker = createCallable<{ title: string; items: readonly Item[] }, Item | null>(ItemPicker);\n\nconst FRUITS: readonly Item[] = [\n  { id: \"apple\", name: \"Apple\", hint: \"🍎\" },\n  { id: \"banana\", name: \"Banana\", hint: \"🍌\" },\n  { id: \"cherry\", name: \"Cherry\", hint: \"🍒\" },\n  { id: \"grape\", name: \"Grape\", hint: \"🍇\" },\n  { id: \"mango\", name: \"Mango\", hint: \"🥭\" }\n];\n\n@Component({\n  selector: \"item-picker-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Pick a fruit</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!picked()\">{{ picked() ? \"→ \" + picked() : \"→ nothing picked yet\" }}</span>\n  `\n})\nexport class ItemPickerExample {\n  protected readonly picked = signal<string | null>(null);\n\n  protected async run(): Promise<void> {\n    const choice = await Picker.call({ title: \"Pick a fruit\", items: FRUITS });\n    this.picked.set(choice ? choice.name : null);\n  }\n}\n",
  "live-status": "import { Component, computed, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));\n\ntype Stage = \"placed\" | \"packing\" | \"shipped\" | \"out\" | \"delivered\";\nconst STAGES: Stage[] = [\"placed\", \"packing\", \"shipped\", \"out\", \"delivered\"];\nconst LABELS: Record<Stage, string> = {\n  placed: \"Order placed\",\n  packing: \"Packing your order\",\n  shipped: \"Handed to carrier\",\n  out: \"Out for delivery\",\n  delivered: \"Delivered\"\n};\n\n// A pinned status pill the caller drives from the outside, by pushing new props\n// into this exact open call via its promise handle.\n@Component({\n  selector: \"live-status\",\n  template: `\n    <div class=\"ad-floating\" [style.right.px]=\"24\" [style.bottom.px]=\"24\">\n      <div class=\"ad-pill\">\n        <div class=\"ad-actions ad-actions--split\" style=\"margin-top: 0\">\n          <div>\n            <p class=\"ad-subtle\">Order #4821</p>\n            <p class=\"ad-body\" style=\"font-size: 0.875rem; font-weight: 500; margin-top: 0.15rem\">{{ label() }}</p>\n          </div>\n          <button class=\"ad-close\" [attr.aria-label]=\"done() ? 'Dismiss' : 'Stop watching'\" (click)=\"call.end()\">×</button>\n        </div>\n        <div class=\"ad-segments\">\n          @for (s of STAGES; track s; let i = $index) {\n            <span [class.is-done]=\"i <= stepIndex()\"></span>\n          }\n        </div>\n      </div>\n    </div>\n  `\n})\nclass LiveStatus {\n  protected readonly STAGES = STAGES;\n  protected readonly call = injectCallRef<{ stage: Stage }, void>();\n  protected readonly stepIndex = computed(() => STAGES.indexOf(this.call.props().stage));\n  protected readonly done = computed(() => this.call.props().stage === \"delivered\");\n  protected label(): string {\n    return LABELS[this.call.props().stage];\n  }\n}\n\nconst Status = createCallable<{ stage: Stage }, void>(LiveStatus);\n\n@Component({\n  selector: \"live-status-example\",\n  template: `<button class=\"btn btn-primary\" [disabled]=\"running()\" (click)=\"run()\">{{ running() ? \"Watching order…\" : \"Place order\" }}</button>`\n})\nexport class LiveStatusExample {\n  protected readonly running = signal(false);\n  private readonly sequence: Stage[] = [\"packing\", \"shipped\", \"out\", \"delivered\"];\n\n  protected async run(): Promise<void> {\n    this.running.set(true);\n    // The promise IS the call's identity — hold it to target updates at it.\n    const promise = Status.call({ stage: \"placed\" });\n\n    let dismissed = false;\n    promise.then(() => (dismissed = true));\n\n    for (const stage of this.sequence) {\n      await sleep(900);\n      if (dismissed) break;\n      Status.update(promise, { stage }); // re-render this one call with new props\n    }\n\n    await promise;\n    this.running.set(false);\n  }\n}\n",
  "nested-dialog": "import { Component, computed } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst DOM_LIMIT = 10; // only render the topmost N instances; older ones stay in the stack\n\n// A callable that opens itself, producing a stack of independent instances —\n// each with its own promise resolved by its own `call.end()`. `index` and\n// `stackSize` are scoped to this callable's own stack.\n@Component({\n  selector: \"nested-dialog\",\n  template: `\n    @if (call.index() >= call.stackSize() - DOM_LIMIT) {\n      <div [class]=\"isTopmost() ? 'ad-overlay' : 'ad-overlay ad-overlay--bare'\" role=\"dialog\" aria-modal=\"true\">\n        <div class=\"ad-panel\" [style.transform]=\"offset()\">\n          <div class=\"ad-actions ad-actions--split\" style=\"margin-top: 0\">\n            <p class=\"ad-subtle\">Level {{ call.props().level }} · #{{ call.index() + 1 }} of {{ call.stackSize() }}</p>\n            <button class=\"ad-close\" aria-label=\"Close\" (click)=\"call.end()\">×</button>\n          </div>\n          <p class=\"ad-body\" style=\"margin-top: 0.75rem\">\n            A Callable can open itself. Each open instance has its own promise, resolved by its own\n            <code>call.end()</code>.\n          </p>\n          <div class=\"ad-actions ad-actions--split\">\n            <button class=\"btn btn-ghost\" (click)=\"closeAll()\">Close all</button>\n            <div class=\"ex-row\">\n              <button class=\"btn\" (click)=\"call.end()\">Close</button>\n              <button class=\"btn btn-primary\" (click)=\"openNested()\">Open nested</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    }\n  `,\n  styles: [`.ad-overlay--bare .ad-panel { pointer-events: auto; }`]\n})\nclass NestedDialog {\n  protected readonly DOM_LIMIT = DOM_LIMIT;\n  protected readonly call = injectCallRef<{ level: number }, void>();\n  protected readonly isTopmost = computed(() => this.call.index() + 1 === this.call.stackSize());\n  protected readonly offset = computed(() => {\n    const px = (this.call.index() % 6) * 18;\n    return `translate(${px}px, ${px}px)`;\n  });\n\n  protected openNested(): void {\n    Nested.call({ level: this.call.props().level + 1 });\n  }\n\n  protected closeAll(): void {\n    Nested.end(); // end every open instance of this callable at once\n  }\n}\n\nconst Nested = createCallable<{ level: number }, void>(NestedDialog);\n\n@Component({\n  selector: \"nested-example\",\n  template: `<button class=\"btn btn-primary\" (click)=\"open()\">Open dialog</button>`\n})\nexport class NestedExample {\n  protected open(): void {\n    Nested.call({ level: 1 });\n  }\n}\n",
  "optional-mutation": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, createMutationFlow, injectCallRef, type MutationFn } from \"ngx-call\";\n\nconst sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));\n\ninterface OptionalProps {\n  message: string;\n  // Optional: typing it as possibly-undefined unlocks `.orEnd(value)`.\n  mutationFn?: MutationFn<boolean>;\n}\n\n// One callable that supports both an instant close and an async handler,\n// depending on whether the caller supplies a mutationFn.\n@Component({\n  selector: \"optional-confirm-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-body\">{{ call.props().message }}</p>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" [disabled]=\"submit.pending()\" (click)=\"call.end(false)\">Cancel</button>\n          <button class=\"btn btn-primary\" [disabled]=\"submit.pending()\" (click)=\"submit().orEnd(true)\">\n            {{ submit.pending() ? \"Working…\" : \"Confirm\" }}\n          </button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass OptionalConfirmDialog {\n  protected readonly call = injectCallRef<OptionalProps, boolean>();\n  protected readonly submit = createMutationFlow(this.call, this.call.props().mutationFn);\n}\n\nconst OptionalConfirm = createCallable<OptionalProps, boolean>(OptionalConfirmDialog);\n\n@Component({\n  selector: \"optional-mutation-example\",\n  template: `\n    <div class=\"ex-row\">\n      <button class=\"btn\" (click)=\"discard()\">Discard draft</button>\n      <button class=\"btn btn-primary\" (click)=\"publish()\">Publish post</button>\n    </div>\n    <span class=\"ex-status\">{{ status() }}</span>\n  `\n})\nexport class OptionalMutationExample {\n  protected readonly status = signal(\"→ awaiting click…\");\n\n  // No mutationFn: `submit().orEnd(true)` closes instantly with the fallback.\n  protected async discard(): Promise<void> {\n    const ok = await OptionalConfirm.call({ message: \"Discard your draft?\" });\n    this.status.set(ok ? \"→ draft discarded\" : \"→ kept\");\n  }\n\n  // With a mutationFn: `.orEnd` is a no-op; the handler owns the close.\n  protected async publish(): Promise<void> {\n    const ok = await OptionalConfirm.call({\n      message: \"Publish this post now?\",\n      mutationFn: async call => {\n        await sleep(900);\n        call.end(true);\n      }\n    });\n    this.status.set(ok ? \"→ published\" : \"→ cancelled\");\n  }\n}\n",
  "permission-prompt": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// An OAuth-style consent prompt. The response is a tagged union — 'allow' or\n// 'deny' — which is self-documenting and extensible (vs a bare boolean).\n@Component({\n  selector: \"permission-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-title\">Allow <span style=\"color: var(--color-accent)\">{{ call.props().appName }}</span> to:</p>\n        <ul style=\"margin: 1rem 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 0.5rem\">\n          @for (s of call.props().scopes; track s) {\n            <li class=\"ad-body\" style=\"display: flex; gap: 0.5rem; font-size: 0.875rem\">\n              <span aria-hidden=\"true\" style=\"color: var(--color-accent)\">✓</span>\n              {{ s }}\n            </li>\n          }\n        </ul>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" (click)=\"call.end('deny')\">Deny</button>\n          <button class=\"btn btn-primary\" (click)=\"call.end('allow')\">Allow</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass PermissionDialog {\n  protected readonly call = injectCallRef<{ appName: string; scopes: readonly string[] }, \"allow\" | \"deny\">();\n}\n\nconst Permission = createCallable<{ appName: string; scopes: readonly string[] }, \"allow\" | \"deny\">(PermissionDialog);\n\n@Component({\n  selector: \"permission-example\",\n  template: `\n    <button class=\"btn btn-primary\" [disabled]=\"status() === 'connected'\" (click)=\"run()\">\n      {{ status() === \"connected\" ? \"Connected\" : \"Connect with GitHub\" }}\n    </button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"status() === 'connected'\">{{ label() }}</span>\n  `\n})\nexport class PermissionExample {\n  protected readonly status = signal<\"idle\" | \"connected\" | \"denied\">(\"idle\");\n  protected label(): string {\n    return this.status() === \"idle\" ? \"→ awaiting consent…\" : this.status() === \"connected\" ? \"→ allowed\" : \"→ denied\";\n  }\n\n  protected async run(): Promise<void> {\n    const result = await Permission.call({\n      appName: \"ngx-call demo\",\n      scopes: [\"Read your profile\", \"Read your repositories\", \"Subscribe to webhook events\"]\n    });\n    this.status.set(result === \"allow\" ? \"connected\" : \"denied\");\n  }\n}\n",
  "progress-toast": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));\nconst TOAST_ROW = 84;\n\n// A singleton toast. `upsert()` creates it on first call, then updates the same\n// instance — so consecutive calls mutate one toast instead of stacking.\n@Component({\n  selector: \"progress-toast\",\n  template: `\n    <div class=\"ad-floating\" role=\"status\" aria-live=\"polite\" [style.right.px]=\"24\" [style.bottom.px]=\"24 + call.index() * TOAST_ROW\">\n      <div class=\"ad-toast\">\n        <div class=\"ad-actions ad-actions--split\" style=\"margin-top: 0\">\n          <p class=\"ad-body\" style=\"font-size: 0.875rem\">{{ call.props().message }}</p>\n          <button class=\"ad-close\" aria-label=\"Dismiss\" (click)=\"call.end()\">×</button>\n        </div>\n        @if (call.props().percent !== undefined) {\n          <div class=\"ad-progress\"><span [style.width.%]=\"clamp(call.props().percent!)\"></span></div>\n        }\n      </div>\n    </div>\n  `\n})\nclass ProgressToast {\n  protected readonly TOAST_ROW = TOAST_ROW;\n  protected readonly call = injectCallRef<{ message: string; percent?: number }, void>();\n  protected clamp(p: number): number {\n    return Math.min(100, Math.max(0, p));\n  }\n}\n\nconst Toast = createCallable<{ message: string; percent?: number }, void>(ProgressToast);\n\n@Component({\n  selector: \"progress-toast-example\",\n  template: `<button class=\"btn btn-primary\" [disabled]=\"running()\" (click)=\"run()\">{{ running() ? \"Downloading…\" : \"Start download\" }}</button>`\n})\nexport class ProgressToastExample {\n  protected readonly running = signal(false);\n\n  protected async run(): Promise<void> {\n    this.running.set(true);\n    let cancelled = false;\n    // The promise is stable for the singleton's lifetime — resolve = dismissed.\n    const session = Toast.upsert({ message: \"Starting download…\", percent: 0 });\n    session.then(() => (cancelled = true));\n\n    for (let i = 10; i <= 100; i += 10) {\n      await sleep(150);\n      if (cancelled) {\n        this.running.set(false);\n        return;\n      }\n      Toast.upsert({ message: `Downloading… ${i}%`, percent: i });\n    }\n    Toast.upsert({ message: \"Done!\", percent: 100 });\n    await sleep(800);\n    Toast.end();\n    this.running.set(false);\n  }\n}\n",
  "prompt-input": "import { afterNextRender, Component, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\n// A component-based alternative to window.prompt(): resolves with the entered\n// string, or null on cancel / empty input. Auto-focuses on open.\n@Component({\n  selector: \"prompt-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <form class=\"ad-panel\" (submit)=\"submit($event)\">\n        <label class=\"ad-title\" for=\"prompt-input\">{{ call.props().title }}</label>\n        <input\n          #input\n          id=\"prompt-input\"\n          class=\"ad-input\"\n          type=\"text\"\n          [value]=\"value()\"\n          [placeholder]=\"call.props().placeholder ?? ''\"\n          (input)=\"value.set($any($event.target).value)\"\n        />\n        <div class=\"ad-actions\">\n          <button type=\"button\" class=\"btn\" (click)=\"call.end(null)\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-primary\">OK</button>\n        </div>\n      </form>\n    </div>\n  `\n})\nclass PromptDialog {\n  protected readonly call = injectCallRef<{ title: string; placeholder?: string; defaultValue?: string }, string | null>();\n  protected readonly value = signal(this.call.props().defaultValue ?? \"\");\n  private readonly input = viewChild.required<ElementRef<HTMLInputElement>>(\"input\");\n\n  constructor() {\n    afterNextRender(() => this.input().nativeElement.focus());\n  }\n\n  protected submit(event: Event): void {\n    event.preventDefault();\n    this.call.end(this.value().trim() || null);\n  }\n}\n\nconst Prompt = createCallable<{ title: string; placeholder?: string; defaultValue?: string }, string | null>(PromptDialog);\n\n@Component({\n  selector: \"prompt-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Rename</button>\n    <span class=\"ex-status ex-status--ok\">→ {{ name() }}</span>\n  `\n})\nexport class PromptExample {\n  protected readonly name = signal(\"untitled-file.txt\");\n\n  protected async run(): Promise<void> {\n    const next = await Prompt.call({ title: \"Rename file\", defaultValue: this.name(), placeholder: \"New filename\" });\n    if (next) this.name.set(next);\n  }\n}\n",
  "root-context": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ninterface GreeterProps {\n  message: string;\n}\n\n// The third generic types the ambient root props — read via `call.root()` —\n// kept separate from the per-call props. The caller never forwards them.\ninterface GreeterRoot {\n  userName: string;\n}\n\n@Component({\n  selector: \"greeter-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-subtle\">Signed in as {{ call.root().userName }}</p>\n        <p class=\"ad-body\" style=\"margin-top: 0.5rem\">{{ call.props().message }}</p>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" (click)=\"call.end(false)\">Not now</button>\n          <button class=\"btn btn-primary\" (click)=\"call.end(true)\">Enable</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass GreeterDialog {\n  protected readonly call = injectCallRef<GreeterProps, boolean, GreeterRoot>();\n}\n\nconst Greeter = createCallable<GreeterProps, boolean, GreeterRoot>(GreeterDialog);\n// Ambient context, set once (the equivalent of mounting <Root userName=\"…\" />).\nGreeter.setRoot({ userName: \"Ada Lovelace\" });\n\n@Component({\n  selector: \"greeter-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Review security</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"status() === 'enabled'\">{{ label() }}</span>\n  `\n})\nexport class GreeterExample {\n  protected readonly status = signal<\"idle\" | \"enabled\" | \"dismissed\">(\"idle\");\n  protected label(): string {\n    return this.status() === \"idle\" ? \"→ awaiting click…\" : this.status() === \"enabled\" ? \"→ 2FA enabled\" : \"→ dismissed\";\n  }\n\n  protected async run(): Promise<void> {\n    // Only the per-call message is passed — userName comes from the root.\n    const enabled = await Greeter.call({ message: \"Enable two-factor authentication for your account?\" });\n    this.status.set(enabled ? \"enabled\" : \"dismissed\");\n  }\n}\n",
  "save-form": "import { Component, signal } from \"@angular/core\";\nimport { createCallable, createMutationFlow, injectCallRef, type MutationFn } from \"ngx-call\";\n\nconst sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));\n\ninterface SaveProps {\n  initialName?: string;\n  mutationFn: MutationFn<string, { name: string; shouldFail: boolean }>;\n}\n\n// `createMutationFlow` wires the dialog to an async action: it tracks `pending`\n// for you, and on failure the call stays open so the user can retry.\n@Component({\n  selector: \"save-form-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\">\n      <div class=\"ad-panel\">\n        <p class=\"ad-title\">Save item</p>\n        <input\n          class=\"ad-input\"\n          type=\"text\"\n          [value]=\"name()\"\n          [disabled]=\"submit.pending()\"\n          placeholder=\"Item name\"\n          (input)=\"name.set($any($event.target).value)\"\n        />\n        <label class=\"ad-check\">\n          <input type=\"checkbox\" [checked]=\"shouldFail()\" [disabled]=\"submit.pending()\" (change)=\"shouldFail.set($any($event.target).checked)\" />\n          Simulate a failed save\n        </label>\n        <div class=\"ad-actions\">\n          <button class=\"btn\" [disabled]=\"submit.pending()\" (click)=\"call.end('')\">Cancel</button>\n          <button class=\"btn btn-primary\" [disabled]=\"submit.pending() || !name().trim()\" (click)=\"submit({ name: name().trim(), shouldFail: shouldFail() })\">\n            {{ submit.pending() ? \"Saving…\" : \"Save\" }}\n          </button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass SaveFormDialog {\n  protected readonly call = injectCallRef<SaveProps, string>();\n  protected readonly name = signal(this.call.props().initialName ?? \"\");\n  protected readonly shouldFail = signal(false);\n  protected readonly submit = createMutationFlow(this.call, this.call.props().mutationFn);\n}\n\nconst SaveForm = createCallable<SaveProps, string>(SaveFormDialog);\n\n@Component({\n  selector: \"save-form-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">New item</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!saved()\">\n      {{ saved() ? '→ saved \"' + saved() + '\"' : \"→ tick “simulate a failed save” to see it stay open\" }}\n    </span>\n  `\n})\nexport class SaveFormExample {\n  protected readonly saved = signal<string | null>(null);\n\n  protected async run(): Promise<void> {\n    const result = await SaveForm.call({\n      mutationFn: async (call, { name, shouldFail }) => {\n        await sleep(900);\n        // Handle errors inside the mutationFn — not calling call.end() leaves\n        // the dialog open so the user can fix things and retry.\n        try {\n          if (shouldFail) throw new Error(\"Saving failed — try again.\");\n          call.end(name);\n        } catch {\n          // surface this however your UI needs; here we just stay open\n        }\n      }\n    });\n    if (result) this.saved.set(result);\n  }\n}\n",
  "side-drawer": "import { afterNextRender, Component, computed, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\nconst UNMOUNT_DELAY = 300;\n\ntype Theme = \"system\" | \"light\" | \"dark\";\n\ninterface Settings {\n  notifications: boolean;\n  syncOnLaunch: boolean;\n  theme: Theme;\n}\n\n// A side panel that owns its own form state, seeded from `initial`. Resolves\n// with the saved Settings, or null on cancel / dismiss. Slides out on close.\n@Component({\n  selector: \"settings-drawer\",\n  host: {\n    \"(document:keydown.escape)\": \"call.end(null)\",\n    \"(document:mousedown)\": \"onDoc($event)\"\n  },\n  template: `\n    <div class=\"ad-overlay ad-overlay--end ad-overlay--animated\" [class.is-closing]=\"!open()\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Settings\">\n      <div #drawer class=\"ad-drawer\" [class.is-closing]=\"!open()\">\n        <div class=\"ad-drawer-head\">\n          <p class=\"ad-title\">Settings</p>\n          <button class=\"ad-close\" aria-label=\"Close\" (click)=\"call.end(null)\">×</button>\n        </div>\n\n        <div class=\"ad-drawer-body\">\n          <div class=\"ad-row\">\n            <div>\n              <p style=\"font-weight: 500; margin: 0\">Notifications</p>\n              <p class=\"hint\">Browser notifications for new mentions.</p>\n            </div>\n            <input type=\"checkbox\" [checked]=\"settings().notifications\" (change)=\"patch({ notifications: $any($event.target).checked })\" />\n          </div>\n          <div class=\"ad-row\">\n            <div>\n              <p style=\"font-weight: 500; margin: 0\">Sync on launch</p>\n              <p class=\"hint\">Fetch latest data on app start.</p>\n            </div>\n            <input type=\"checkbox\" [checked]=\"settings().syncOnLaunch\" (change)=\"patch({ syncOnLaunch: $any($event.target).checked })\" />\n          </div>\n          <div class=\"ad-row\">\n            <div>\n              <p style=\"font-weight: 500; margin: 0\">Theme</p>\n              <p class=\"hint\">Visual theme used across the app.</p>\n            </div>\n            <select class=\"ad-select\" style=\"width: auto; margin: 0\" [value]=\"settings().theme\" (change)=\"patch({ theme: $any($event.target).value })\">\n              <option value=\"system\">System</option>\n              <option value=\"light\">Light</option>\n              <option value=\"dark\">Dark</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"ad-drawer-foot\">\n          <button class=\"btn\" (click)=\"call.end(null)\">Cancel</button>\n          <button class=\"btn btn-primary\" (click)=\"call.end(settings())\">Save</button>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass SettingsDrawer {\n  protected readonly call = injectCallRef<{ initial: Settings }, Settings | null>();\n  protected readonly settings = signal<Settings>(this.call.props().initial);\n  private readonly drawer = viewChild.required<ElementRef<HTMLElement>>(\"drawer\");\n  private readonly entered = signal(false);\n  protected readonly open = computed(() => this.entered() && !this.call.ended());\n\n  constructor() {\n    afterNextRender(() => this.entered.set(true));\n  }\n\n  protected patch(part: Partial<Settings>): void {\n    this.settings.update(s => ({ ...s, ...part }));\n  }\n\n  protected onDoc(event: MouseEvent): void {\n    if (!this.drawer().nativeElement.contains(event.target as Node)) this.call.end(null);\n  }\n}\n\nconst Drawer = createCallable<{ initial: Settings }, Settings | null>(SettingsDrawer, UNMOUNT_DELAY);\n\n@Component({\n  selector: \"settings-drawer-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Open settings</button>\n    <span class=\"ex-status\">\n      notifications={{ settings().notifications }} · sync={{ settings().syncOnLaunch }} · theme={{ settings().theme }}\n    </span>\n  `\n})\nexport class SettingsDrawerExample {\n  protected readonly settings = signal<Settings>({ notifications: true, syncOnLaunch: false, theme: \"system\" });\n\n  protected async run(): Promise<void> {\n    const next = await Drawer.call({ initial: this.settings() });\n    if (next) this.settings.set(next);\n  }\n}\n",
  "wizard": "import { Component, effect, ElementRef, signal, viewChild } from \"@angular/core\";\nimport { createCallable, injectCallRef } from \"ngx-call\";\n\ninterface WizardResult {\n  name: string;\n  email: string;\n  plan: \"free\" | \"pro\" | \"team\";\n}\n\n// A three-step signup. All step state lives inside the dialog; the caller awaits\n// a single structured response (or null on cancel).\n@Component({\n  selector: \"wizard-dialog\",\n  template: `\n    <div class=\"ad-overlay\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Wizard\">\n      <div class=\"ad-panel\" style=\"max-width: 28rem\">\n        <div class=\"ad-steps\">\n          @for (i of [0, 1, 2]; track i) {\n            <span [class.is-done]=\"i <= step()\"></span>\n          }\n        </div>\n\n        @if (step() === 0) {\n          <p class=\"ad-subtle\">Step 1 of 3</p>\n          <p class=\"ad-title\" style=\"margin-top: 0.25rem\">Your name</p>\n          <input #nameInput class=\"ad-input\" style=\"margin-top: 1rem\" type=\"text\" placeholder=\"Ada Lovelace\" [value]=\"name()\" (input)=\"name.set($any($event.target).value)\" />\n        }\n        @if (step() === 1) {\n          <p class=\"ad-subtle\">Step 2 of 3</p>\n          <p class=\"ad-title\" style=\"margin-top: 0.25rem\">Your email</p>\n          <input #emailInput class=\"ad-input\" style=\"margin-top: 1rem\" type=\"email\" placeholder=\"ada@example.com\" [value]=\"email()\" (input)=\"email.set($any($event.target).value)\" />\n        }\n        @if (step() === 2) {\n          <p class=\"ad-subtle\">Step 3 of 3</p>\n          <p class=\"ad-title\" style=\"margin-top: 0.25rem\">Pick a plan</p>\n          <div style=\"display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.5rem; margin-top: 1rem\">\n            @for (p of plans; track p) {\n              <button class=\"btn\" [class.btn-primary]=\"p === plan()\" (click)=\"plan.set(p)\">{{ p }}</button>\n            }\n          </div>\n        }\n\n        <div class=\"ad-actions ad-actions--split\">\n          <button class=\"btn btn-ghost\" (click)=\"call.end(null)\">Cancel</button>\n          <div class=\"ex-row\">\n            @if (step() > 0) {\n              <button class=\"btn\" (click)=\"step.set(step() - 1)\">Back</button>\n            }\n            @if (step() < 2) {\n              <button class=\"btn btn-primary\" [disabled]=\"nextDisabled()\" (click)=\"step.set(step() + 1)\">Next</button>\n            } @else {\n              <button class=\"btn btn-primary\" (click)=\"finish()\">Finish</button>\n            }\n          </div>\n        </div>\n      </div>\n    </div>\n  `\n})\nclass WizardDialog {\n  protected readonly call = injectCallRef<void, WizardResult | null>();\n  protected readonly plans = [\"free\", \"pro\", \"team\"] as const;\n  protected readonly step = signal(0);\n  protected readonly name = signal(\"\");\n  protected readonly email = signal(\"\");\n  protected readonly plan = signal<WizardResult[\"plan\"]>(\"free\");\n  private readonly nameInput = viewChild<ElementRef<HTMLInputElement>>(\"nameInput\");\n  private readonly emailInput = viewChild<ElementRef<HTMLInputElement>>(\"emailInput\");\n\n  constructor() {\n    effect(() => {\n      if (this.step() === 0) this.nameInput()?.nativeElement.focus();\n      if (this.step() === 1) this.emailInput()?.nativeElement.focus();\n    });\n  }\n\n  protected nextDisabled(): boolean {\n    return (this.step() === 0 && !this.name().trim()) || (this.step() === 1 && !this.email().trim());\n  }\n\n  protected finish(): void {\n    this.call.end({ name: this.name(), email: this.email(), plan: this.plan() });\n  }\n}\n\nconst Wizard = createCallable<void, WizardResult | null>(WizardDialog);\n\n@Component({\n  selector: \"wizard-example\",\n  template: `\n    <button class=\"btn btn-primary\" (click)=\"run()\">Sign up</button>\n    <span class=\"ex-status\" [class.ex-status--ok]=\"!!result()\">\n      {{ result() ? \"→ \" + result()!.name + \" (\" + result()!.plan + \")\" : \"→ no signup yet\" }}\n    </span>\n  `\n})\nexport class WizardExample {\n  protected readonly result = signal<WizardResult | null>(null);\n\n  protected async run(): Promise<void> {\n    const data = await Wizard.call();\n    if (data) this.result.set(data);\n  }\n}\n"
};
